pub type Student = {
  name: Str;
  grade: Int;
}

impl Eq for Student {
  fn equals(self: &Student, other: &Student) -> Bool { return self.name == other.name; }
}

impl Display for Student {
  fn to_str(self: &Student) -> Str { return self.name + " (" + self.grade.to_str() + ")"; }
}

impl Ord for Student {
  fn compare(self: &Student, other: &Student) -> Ordering {
    if self.grade < other.grade { return Ordering::Less; }
    if self.grade > other.grade { return Ordering::Greater; }
    return Ordering::Equal;
  }
}

fn main() -> Int {
  let s1 = Student{ name: "Alice", grade: 85 };
  let s2 = Student{ name: "Bob", grade: 92 };
  let s3 = Student{ name: "Carol", grade: 78 };
  if s2 > s1 && s2 > s3 { return s2.grade; }
  return 0;
}
